async function open(next){if(!api.user())return;route={...next};if(route.view==='home'&&members.length===1)route={view:'team',team:members[0].team_id};if(route.team&&!has(route.team)){route={view:'home'};}if(route.view==='settings'&&!rootAdmin())route={view:'home'};if(route.view==='teamadmin'&&!isAdmin(route.team))route={view:'team',team:route.team};const area=route.view==='links'?'spreadsheets':['training','projects','meetings'].includes(route.view)?route.view:null;if(area&&(!assigned(route.team,area)||!allowed(route.team,area)))route={view:'team',team:route.team};if(route.view==='home'&&members.length===1)route={view:'team',team:members[0].team_id};GuhuzaUI.show('portal');const root=$('portalPanel'),ticket=++run;root.replaceChildren();crumb(root);const body=el('div');root.append(body);try{if(!loaded)throw Error('Team access is still loading. Use Refresh to retry.');if(route.view==='home')home(body);else if(route.view==='team')teamHome(body);else if(route.view==='training'||route.view==='links')await resources(body,route.view);else if(route.view==='projects')await projects(body);else if(route.view==='settings')await settings(body);else if(route.view==='meetings')await GuhuzaMeetings.render({root:body,team:route.team,day:route.meetingDay,api});else if(route.view==='teamadmin')await teamAdminHub(body);else home(body);}catch(e){if(ticket===run){notice(body,e.message);body.append(button('Retry',()=>open(route)));}}if(ticket===run)window.GuhuzaNavigation?.save();}

